ON CONFLICT (key) DO NOTHING;

UPDATE sources SET status='ACTIVE',legal_status='ALLOWED',kill_switch=false,rate_limit_rpm=2,updated_at=now() WHERE key='the-robot-report';

SELECT key,homepage_url,'RSS_METADATA','Operator-approved RSS metadata discovery: retain title, date, categories and canonical URL only.','["title","published_at","categories","canonical_url"]','["metadata_discovery","deduplication"]','No raw RSS, HTML, images, excerpts or article bodies retained.','Only high-relevance July 2026+ metadata; link to original.','Maximum two requests per minute, one request per feed per run.','Canonical URL','rss-metadata-v1','1' FROM sources WHERE key IN ('techxplore-robotics','robotics-247','robotics-automation-news','robohub','humanoid-guide-news','the-robot-report') AND NOT EXISTS (SELECT 1 FROM source_contracts c WHERE c.source_key=sources.key);

UPDATE scheduled_agents SET implementation_status='READY',is_enabled=true,cron_expression='5 */6 * * *',source_keys='["techxplore-robotics","robotics-247","robotics-automation-news","robohub","humanoid-guide-news","the-robot-report"]'::jsonb,description='Collects July 2026+ robotics-news metadata from approved RSS feeds, filters for high relevance and deduplicates by canonical URL and similar title. It never stores article HTML or images.' WHERE agent_key='insights-metadata-collector';
